css:
.totalreward-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20242e;
    background: linear-gradient(160deg, #f4f1ea 0%, #ece7db 100%);
    border-radius: 18px;
}

.totalreward-container * {
    box-sizing: border-box;
}

.totalreward-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #14342b 0%, #1f5848 55%, #2f7d5f 100%);
    color: #f3f9f4;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(20, 52, 43, 0.30);
}

.totalreward-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.totalreward-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #f0d9a6;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.totalreward-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dcefe1;
}

.totalreward-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #234a3d;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.totalreward-period-counter #currentDay,
.totalreward-period-counter #maxPeriods {
    font-weight: 800;
    color: #14342b;
}

.totalreward-round-name {
    background: #d6e9dd;
    color: #14342b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.totalreward-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a5a12;
    background: #f7eccd;
    padding: 4px 12px;
    border-radius: 999px;
}

.totalreward-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.totalreward-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0dccf;
    box-shadow: 0 4px 14px rgba(20, 52, 43, 0.06);
    border-top: 4px solid #2f7d5f;
}

.totalreward-card-equity { border-top-color: #1f5848; }
.totalreward-card-retention { border-top-color: #2f6fb0; }
.totalreward-card-motivation { border-top-color: #b5882a; }
.totalreward-card-fairness { border-top-color: #7a4fb0; }

.totalreward-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7064;
}

.totalreward-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14342b;
}

.totalreward-card-equity .totalreward-value { color: #1f5848; }
.totalreward-card-retention .totalreward-value { color: #2f6fb0; }
.totalreward-card-motivation .totalreward-value { color: #b5882a; }
.totalreward-card-fairness .totalreward-value { color: #7a4fb0; }

.totalreward-sublabel {
    font-size: 0.76rem;
    color: #7d8276;
    line-height: 1.35;
}

.totalreward-kpi-low .totalreward-value { color: #c0392b; }
.totalreward-kpi-target .totalreward-value { color: #1f7a4d; }

.totalreward-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #14342b;
    color: #eaf6ee;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.totalreward-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.totalreward-budget-over #budgetDisplay {
    color: #ffb1a3;
}

.totalreward-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f7d5f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 52, 43, 0.05);
}

.totalreward-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.totalreward-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14342b;
    margin-bottom: 6px;
}

.totalreward-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #34403a;
}

.totalreward-briefing-text strong { color: #1f7a4d; }
.totalreward-briefing-text em { color: #8a5a12; font-style: italic; }

.totalreward-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0dccf;
    box-shadow: 0 4px 14px rgba(20, 52, 43, 0.06);
}

.totalreward-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14342b;
    border-bottom: 2px solid #ece7db;
    padding-bottom: 8px;
}

.totalreward-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #233f35;
    margin: 14px 0 6px;
}

.totalreward-container select,
.totalreward-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9d6cd;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f8fbf9;
    color: #20242e;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.totalreward-container select:focus,
.totalreward-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7d5f;
    box-shadow: 0 0 0 3px rgba(47, 125, 95, 0.15);
}

.totalreward-container select option {
    background-color: #ffffff;
    color: #20242e;
}

.totalreward-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7d5f;
}

.totalreward-range-readout,
.totalreward-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #1f5848;
    margin-top: 4px;
}

.totalreward-range-readout span:last-child,
.totalreward-alloc-readout span:nth-child(2) {
    color: #1f7a4d;
    font-weight: 800;
}

.totalreward-hint {
    font-size: 0.8rem;
    color: #7d8276;
    margin-top: 4px;
    line-height: 1.4;
}

.totalreward-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.totalreward-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f8f5;
    border: 1px solid #dde9e1;
    border-radius: 9px;
    padding: 8px 12px;
}

.totalreward-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #233f35;
}

.totalreward-alloc-row input[type="number"] {
    width: 96px;
    flex: 0 0 96px;
}

.totalreward-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.totalreward-container .btn-primary {
    background: linear-gradient(135deg, #1f5848 0%, #2f7d5f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(31, 88, 72, 0.28);
}

.totalreward-container .btn-primary:hover {
    filter: brightness(1.07);
}

.totalreward-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c9d6cd;
    color: #6b7064;
}

.totalreward-coach {
    background: #14342b;
    color: #eaf6ee;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(20, 52, 43, 0.22);
}

.totalreward-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8ed3ad;
    margin-bottom: 8px;
}

.totalreward-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.totalreward-coach-body strong { color: #f0d9a6; }
.totalreward-coach-body em { color: #ffc9a8; font-style: italic; }

.totalreward-history,
.totalreward-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0dccf;
    box-shadow: 0 4px 14px rgba(20, 52, 43, 0.06);
}

.totalreward-history h3,
.totalreward-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14342b;
}

.totalreward-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #233f35;
}

.totalreward-container table#usfHistoryTable th {
    background: #eaf3ee;
    color: #14342b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e6db;
}

.totalreward-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef4f0;
}

.totalreward-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fbf9;
}

.totalreward-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .totalreward-container {
        padding: 14px;
    }
    .totalreward-header h1 {
        font-size: 1.7rem;
    }
    .totalreward-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .totalreward-value {
        font-size: 2rem;
    }
    .totalreward-clock {
        margin-left: 0;
    }
    .totalreward-period-counter {
        font-size: 0.88rem;
    }
    .totalreward-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .totalreward-alloc-row {
        flex-wrap: wrap;
    }
    .totalreward-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .totalreward-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (totalreward) ---- */
.totalreward-completion { padding: 8px 4px 4px; }
.totalreward-cm-head { text-align: center; margin-bottom: 16px; }
.totalreward-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #5a6a3a; }
.totalreward-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #93a17b; }
.totalreward-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #2c3322; }
.totalreward-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.totalreward-cm-yes { background: rgba(90,106,58,0.16); color: #5a6a3a; border: 1px solid rgba(90,106,58,0.5); }
.totalreward-cm-no { background: rgba(180,70,55,0.12); color: #a5412c; border: 1px solid rgba(180,70,55,0.45); }
.totalreward-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.totalreward-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(90,106,58,0.08); border: 1px solid rgba(90,106,58,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.totalreward-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #5a6a3a; }
.totalreward-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #656b7c; text-transform: uppercase; letter-spacing: 0.03em; }
.totalreward-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #2c3322; }
.totalreward-cm-insights { margin: 0; padding-left: 20px; }
.totalreward-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #363c4b; }

