(function() {
    'use strict';

    class TotalRewardAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Total Reward`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // NUMBERS REFERENCE CARD.
            this.ENVELOPE = 5.04;            // €M, the +3% payroll cap
            this.FULL_DEMAND = 8.3;          // €M, all three segments' full claims (~60% funded)
            this.MGMT_NORM_LOW = 18;         // sector norm for management variable pay (%)
            this.MGMT_NORM_HIGH = 22;

            // KPI starting points (low, with headroom — no meter pegged before R4).
            this.START_EQUITY = 30;
            this.START_RETENTION = 25;
            this.START_MOTIVATION = 20;
            this.START_FAIRNESS = 35;

            // Concept-correct keys (the integral-compensation play).
            this.TRUE_FRAME = `portfolio`;
            this.TRUE_PRIORITY = `three`;
            this.TRUE_MOTIVDIAG = `linesight`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    equity: this.START_EQUITY,
                    retention: this.START_RETENTION,
                    motivation: this.START_MOTIVATION,
                    fairness: this.START_FAIRNESS,
                    committed: 0,            // €M committed (running, set in R2)
                    overspent: false,        // breached the +3% envelope
                    paperRedistribution: false,
                    equityHistory: [this.START_EQUITY],
                    retentionHistory: [this.START_RETENTION],
                    motivationHistory: [this.START_MOTIVATION],
                    fairnessHistory: [this.START_FAIRNESS],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed MIDDLING / NEUTRAL defaults — a click-through must not auto-win.
                state.decisions = {
                    frame: `flatraise`,
                    priority: `equity`,
                    motivDiag: `toolow`,
                    rigour: 50,
                    frontline: 1.70,
                    specialist: 1.70,
                    management: 1.00,
                    frontMix: `allbase`,
                    specMix: `benefits`,
                    mgmtVar: 12,
                    equityPace: `fullnow`,
                    balance: `internal`,
                    council: `impose`,
                    lineOfSight: 50,
                    pitch: `redistribute`,
                    scorecard: `budget`,
                    defer: `nothing`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const fr = document.getElementById(`frameInput`);
                const pr = document.getElementById(`priorityInput`);
                const md = document.getElementById(`motivDiagInput`);
                const rg = document.getElementById(`rigourInput`);
                if (fr) decisions.frame = fr.value;
                if (pr) decisions.priority = pr.value;
                if (md) decisions.motivDiag = md.value;
                if (rg) decisions.rigour = parseInt(rg.value, 10);
                if (!Number.isFinite(decisions.rigour) || decisions.rigour < 0 || decisions.rigour > 100) {
                    warn(`warn_rigour_range`); return false;
                }
            } else if (round === 2) {
                const fl = document.getElementById(`frontlineInput`);
                const sp = document.getElementById(`specialistInput`);
                const mg = document.getElementById(`managementInput`);
                const fm = document.getElementById(`frontMixInput`);
                const sm = document.getElementById(`specMixInput`);
                const mv = document.getElementById(`mgmtVarInput`);
                if (fl) decisions.frontline = parseFloat(fl.value);
                if (sp) decisions.specialist = parseFloat(sp.value);
                if (mg) decisions.management = parseFloat(mg.value);
                if (fm) decisions.frontMix = fm.value;
                if (sm) decisions.specMix = sm.value;
                if (mv) decisions.mgmtVar = parseInt(mv.value, 10);
                const alloc = [decisions.frontline, decisions.specialist, decisions.management];
                if (alloc.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                if (!Number.isFinite(decisions.mgmtVar) || decisions.mgmtVar < 8 || decisions.mgmtVar > 30) {
                    warn(`warn_mgmtvar_range`); return false;
                }
                // The envelope is a hard +3% cap. Overspend is allowed to be ENTERED but
                // penalised in scoring (Common Error 5) — we only block negatives here.
            } else if (round === 3) {
                const ep = document.getElementById(`equityPaceInput`);
                const ba = document.getElementById(`balanceInput`);
                const co = document.getElementById(`councilInput`);
                const ls = document.getElementById(`lineOfSightInput`);
                if (ep) decisions.equityPace = ep.value;
                if (ba) decisions.balance = ba.value;
                if (co) decisions.council = co.value;
                if (ls) decisions.lineOfSight = parseInt(ls.value, 10);
                if (!Number.isFinite(decisions.lineOfSight) || decisions.lineOfSight < 0 || decisions.lineOfSight > 100) {
                    warn(`warn_lineofsight_range`); return false;
                }
            } else if (round === 4) {
                const pi = document.getElementById(`pitchInput`);
                const sc = document.getElementById(`scorecardInput`);
                const df = document.getElementById(`deferInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pi) decisions.pitch = pi.value;
                if (sc) decisions.scorecard = sc.value;
                if (df) decisions.defer = df.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Per-round deltas on each KPI (start low, build headroom).
            let dEquity = 0, dRetention = 0, dMotivation = 0, dFairness = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose total reward as a PORTFOLIO and accept that the envelope funds ~60%.
                switch (d.frame) {
                    case `portfolio`: dEquity += 6; dRetention += 6; dMotivation += 6; dFairness += 6; coachKey = `coach_r1_portfolio`; break;
                    case `flatraise`: dEquity += 2; dRetention -= 4; dMotivation -= 6; dFairness += 1; coachKey = `coach_r1_flatraise`; break;
                    case `equityonly`: dEquity += 5; dRetention -= 5; dMotivation -= 4; dFairness += 2; coachKey = `coach_r1_equityonly`; break;
                    case `market`: dEquity -= 4; dRetention += 5; dMotivation -= 2; dFairness -= 4; coachKey = `coach_r1_market`; break;
                }

                // Reading of the envelope: all three legitimate, sequence and trade off.
                switch (d.priority) {
                    case `three`: dEquity += 5; dRetention += 5; dMotivation += 5; dFairness += 6; if (d.frame === `portfolio`) coachKey = `coach_r1_sharp`; break;
                    case `equity`: dEquity += 6; dRetention -= 6; dMotivation -= 2; dFairness += 3; break;
                    case `specialists`: dEquity -= 5; dRetention += 7; dMotivation -= 1; dFairness -= 3; break;
                    case `everyone`: dEquity += 2; dRetention += 2; dMotivation += 2; dFairness -= 5; coachKey = `coach_r1_everyone`; break;
                }

                // Why management variable pay fails: line-of-sight, not size.
                switch (d.motivDiag) {
                    case `linesight`: dMotivation += 7; dFairness += 2; break;
                    case `toolow`: dMotivation += 1; break;
                    case `unfair`: dMotivation -= 5; dFairness -= 2; coachKey = `coach_r1_unfair`; break;
                }

                // Diagnostic rigour quantifies the gaps in euros.
                if (d.rigour >= 70) { dEquity += 4; dRetention += 3; dFairness += 3; }
                else if (d.rigour <= 30) { dEquity -= 4; dRetention -= 3; coachKey = `coach_r1_lowrigour`; }

                summaryKey = (d.frame === this.TRUE_FRAME && d.priority === this.TRUE_PRIORITY) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Allocate the €5.04M and rebalance the mix per segment.
                const total = Math.round((d.frontline + d.specialist + d.management) * 100) / 100;
                ds.committed = total;
                const over = total - this.ENVELOPE;

                // Overspending the +3% envelope in a thin-margin business (Common Error 5).
                if (over > 0.001) {
                    ds.overspent = true;
                    const penalty = Math.min(28, Math.round(over * 14)); // scales with the breach
                    dFairness -= penalty; dEquity -= Math.round(penalty / 3); dRetention -= Math.round(penalty / 4);
                    coachKey = `coach_r2_overspend`;
                } else {
                    ds.overspent = false;
                    // Reward using a meaningful share of the envelope (don't leave it idle).
                    if (total >= 4.6) { dFairness += 3; }
                    else if (total < 3.0) { dEquity -= 2; dRetention -= 2; }
                }

                // Frontline lever mix — base correction + cost-efficient benefits fits what they value.
                switch (d.frontMix) {
                    case `basebenefits`: dEquity += 7; dFairness += 5; coachKey = (coachKey === `coach_default`) ? `coach_r2_basebenefits` : coachKey; break;
                    case `allbase`: dEquity += 4; dFairness += 1; dMotivation -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r2_allbase` : coachKey; break;
                    case `allvariable`: dEquity -= 3; dFairness -= 6; coachKey = `coach_r2_frontvariable`; break;
                }

                // Specialist lever mix — base toward market median is the cash they actually weigh.
                const frontShare = total > 0 ? d.frontline / total : 0;
                switch (d.specMix) {
                    case `basemarket`: dRetention += 9; if (d.specialist >= 1.4) dRetention += 3; break;
                    case `benefits`: dRetention -= 4; coachKey = `coach_r2_specbenefits`; break;
                    case `token`: dRetention -= 7; coachKey = `coach_r2_spectoken`; break;
                }

                // Under-funding specialists while over-funding frontline = Common Error 2.
                if (frontShare >= 0.55 && d.specialist <= 1.0) {
                    dRetention -= 6; coachKey = `coach_r2_starvespec`;
                }

                // Lift management variable pay toward the 18–22% norm (without over-inflating).
                if (d.mgmtVar >= this.MGMT_NORM_LOW && d.mgmtVar <= this.MGMT_NORM_HIGH) {
                    dMotivation += 8;
                } else if (d.mgmtVar > this.MGMT_NORM_HIGH) {
                    dMotivation += 3; dFairness -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r2_mgmttoohigh` : coachKey;
                } else if (d.mgmtVar <= 10) {
                    dMotivation += 1;
                } else {
                    dMotivation += 4;
                }

                summaryKey = ds.overspent ? `sum_r2_over`
                    : (d.frontMix === `basebenefits` && d.specMix === `basemarket` && d.mgmtVar >= this.MGMT_NORM_LOW && d.mgmtVar <= this.MGMT_NORM_HIGH) ? `sum_r2_good`
                    : `sum_r2_weak`;
            } else if (round === 3) {
                // Equity constraint & fairness trade-offs.
                // Pace: close credibly now and phase the rest beats both extremes.
                switch (d.equityPace) {
                    case `phased`: dEquity += 9; dRetention += 4; dFairness += 6; coachKey = `coach_r3_phased`; break;
                    case `fullnow`: dEquity += 11; dRetention -= 8; dFairness += 4; coachKey = `coach_r3_fullnow`; break;
                    case `defer`: dEquity -= 6; dRetention += 4; dFairness -= 8; coachKey = `coach_r3_defer`; break;
                }

                // Reconcile internal equity with external competitiveness.
                switch (d.balance) {
                    case `both`: dEquity += 5; dRetention += 7; dFairness += 4; if (d.equityPace === `phased`) coachKey = `coach_r3_both`; break;
                    case `internal`: dEquity += 4; dRetention -= 9; dFairness += 1; coachKey = `coach_r3_internal`; break;
                    case `external`: dEquity -= 8; dRetention += 6; dFairness -= 5; coachKey = `coach_r3_external`; break;
                }

                // Works-council position — negotiate and reserve a concession to trade.
                switch (d.council) {
                    case `negotiate`: dFairness += 8; dEquity += 2; break;
                    case `impose`: dFairness -= 11; coachKey = `coach_r3_impose`; break;
                    case `capitulate`: dFairness += 4; dRetention -= 6; dMotivation -= 4; coachKey = `coach_r3_capitulate`; break;
                }

                // Line-of-sight design — variable pay only motivates when effort→reward is visible.
                if (d.lineOfSight >= 70) { dMotivation += 9; }
                else if (d.lineOfSight >= 45) { dMotivation += 4; }
                else { dMotivation -= 5; coachKey = `coach_r3_noline`; }

                summaryKey = (d.equityPace === `phased` && d.balance === `both` && d.council === `negotiate`) ? `sum_r3_good`
                    : (d.council === `impose` ? `sum_r3_dispute` : `sum_r3_weak`);
            } else if (round === 4) {
                // Defend the package — fair AND affordable, on a four-metric scorecard.
                switch (d.pitch) {
                    case `affordable`: dEquity += 4; dRetention += 4; dMotivation += 6; dFairness += 6; coachKey = `coach_r4_affordable`; break;
                    case `overspend`: dFairness -= 10; dEquity -= 2; coachKey = `coach_r4_overspend`; if (!ds.overspent) ds.overspent = true; break;
                    case `redistribute`: dMotivation -= 6; dFairness -= 4; ds.paperRedistribution = true; coachKey = `coach_r4_redistribute`; break;
                }

                // The scorecard you commit to the board.
                switch (d.scorecard) {
                    case `four`: dFairness += 6; dMotivation += 4; dEquity += 2; dRetention += 2; break;
                    case `budget`: dFairness -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r4_budgetonly` : coachKey; break;
                    case `none`: dFairness -= 7; dMotivation -= 3; coachKey = `coach_r4_noscorecard`; break;
                }

                // What you deliberately defer and phase next year.
                switch (d.defer) {
                    case `phaseplan`: dFairness += 7; dRetention += 3; if (d.pitch === `affordable`) coachKey = `coach_r4_phaseplan`; break;
                    case `nothing`: dFairness -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r4_defernothing` : coachKey; break;
                    case `silent`: dFairness -= 9; coachKey = `coach_r4_defersilent`; break;
                }

                // Conviction that the mix beats a flat raise.
                if (d.conviction >= 70) { dMotivation += 3; dFairness += 2; }
                else if (d.conviction <= 30) { dFairness -= 3; }

                summaryKey = (d.pitch === `affordable` && d.scorecard === `four` && d.defer === `phaseplan` && !ds.overspent) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with floors/caps. Caps keep headroom: nothing pegs at 100 before R4.
            ds.equity = Math.max(0, Math.min(100, ds.equity + dEquity));
            ds.retention = Math.max(0, Math.min(100, ds.retention + dRetention));
            ds.motivation = Math.max(0, Math.min(100, ds.motivation + dMotivation));
            ds.fairness = Math.max(0, Math.min(100, ds.fairness + dFairness));

            ds.equityHistory.push(Math.round(ds.equity));
            ds.retentionHistory.push(Math.round(ds.retention));
            ds.motivationHistory.push(Math.round(ds.motivation));
            ds.fairnessHistory.push(Math.round(ds.fairness));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            const composite = Math.round(
                ds.equity * 0.28 + ds.retention * 0.26 + ds.motivation * 0.22 + ds.fairness * 0.24
            );

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                equity: Math.round(ds.equity),
                retention: Math.round(ds.retention),
                motivation: Math.round(ds.motivation),
                fairness: Math.round(ds.fairness),
                committed: Math.round(ds.committed * 100) / 100,
                overspent: ds.overspent,
                composite: composite,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            const self = this;
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const meter = (id, cls, target) => {
                uiManager.bind(id, `domainState.` + cls, (v) => {
                    const card = document.querySelector(`.totalreward-card-` + cls);
                    if (card) {
                        card.classList.toggle(`totalreward-kpi-target`, Number(v) >= target);
                        card.classList.toggle(`totalreward-kpi-low`, Number(v) < 40);
                    }
                    return Math.round(Number(v));
                });
            };
            meter(`equityDisplay`, `equity`, 75);
            meter(`retentionDisplay`, `retention`, 70);
            meter(`motivationDisplay`, `motivation`, 70);
            meter(`fairnessDisplay`, `fairness`, 70);

            uiManager.bind(`budgetDisplay`, `domainState.committed`, (v) => {
                const bar = document.querySelector(`.totalreward-budget-bar`);
                const over = Number(v) > self.ENVELOPE + 0.001;
                if (bar) bar.classList.toggle(`totalreward-budget-over`, over);
                return self._money(Number(v)) + ` / ` + self._money(self.ENVELOPE);
            });

            // Round 1 — rigour slider readout.
            this._wireSlider(`rigourInput`, `rigourReadout`);
            // Round 3 — line-of-sight slider readout.
            this._wireSlider(`lineOfSightInput`, `lineOfSightReadout`);

            // Round 2 — live envelope total + over-cap colour.
            const allocIds = [`frontlineInput`, `specialistInput`, `managementInput`];
            const envReadout = document.getElementById(`envelopeReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                if (envReadout) envReadout.textContent = total.toFixed(2);
                const readoutEl = document.querySelector(`.totalreward-alloc-readout`);
                if (readoutEl) readoutEl.style.color = (total > self.ENVELOPE + 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        _wireSlider(inputId, readoutId) {
            const input = document.getElementById(inputId);
            const readout = document.getElementById(readoutId);
            if (input && readout) {
                readout.textContent = input.value;
                input.addEventListener(`input`, function() { readout.textContent = input.value; });
            }
        }

        _money(m) {
            // Locale-aware EUR: EN "€2.40M" (symbol before), ES "2,40 M€" (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const val = Number(m);
            if (lang === `es`) {
                return val.toFixed(2).replace(`.`, `,`) + ` M€`;
            }
            return `€` + val.toFixed(2) + `M`;
        }

