        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.equityHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                rewardChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.equityHistory },
                        { data: ds.retentionHistory },
                        { data: ds.motivationHistory },
                        { data: ds.fairnessHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const equity = Math.round(ds.equity);
            const retention = Math.round(ds.retention);
            const motivation = Math.round(ds.motivation);
            const fairness = Math.round(ds.fairness);
            return Math.max(0, Math.min(100, Math.round(equity * 0.28 + retention * 0.26 + motivation * 0.22 + fairness * 0.24)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const equity = Math.round(ds.equity);
            const retention = Math.round(ds.retention);
            const motivation = Math.round(ds.motivation);
            const fairness = Math.round(ds.fairness);
            const composite = this._composite(ds);

            const balanced = equity >= 70 && retention >= 65 && motivation >= 65 && fairness >= 65;

            let performance = window.mySimulation.t(`perf_revolt`);
            if (ds.overspent) performance = window.mySimulation.t(`perf_vetoed`);
            else if (balanced && composite >= 77) performance = window.mySimulation.t(`perf_integral`);
            else if (composite >= 66) performance = window.mySimulation.t(`perf_credible`);
            else if (composite >= 52) performance = window.mySimulation.t(`perf_partial`);

            const insights = [];
            if (ds.overspent) insights.push(window.mySimulation.t(`insight_overspend`));
            if (balanced && composite >= 77 && !ds.overspent) insights.push(window.mySimulation.t(`insight_integral`));
            if (equity < 50) insights.push(window.mySimulation.t(`insight_equity`));
            if (retention < 50) insights.push(window.mySimulation.t(`insight_retention`));
            if (motivation < 50) insights.push(window.mySimulation.t(`insight_motivation`));
            if (fairness < 50) insights.push(window.mySimulation.t(`insight_fairness`));
            if (ds.paperRedistribution) insights.push(window.mySimulation.t(`insight_redistribute`));
            if (!insights.length) insights.push(window.mySimulation.t(`insight_solid`));

            return {
                equity: equity,
                retention: retention,
                motivation: motivation,
                fairness: fairness,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: (!ds.overspent && balanced && composite >= 77),
                overspent: ds.overspent,
                performance: performance,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="totalreward-cm-badge totalreward-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="totalreward-cm-badge totalreward-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.overspent) failBadge += ` <span class="totalreward-cm-badge totalreward-cm-no">` + T(`cm_overspent`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="totalreward-cm-metric"><span class="totalreward-cm-mv">` + Math.round(s.equity || 0) + `</span><span class="totalreward-cm-ml">` + T(`cm_m_equity`) + `</span></div>`
                + `<div class="totalreward-cm-metric"><span class="totalreward-cm-mv">` + Math.round(s.retention || 0) + `</span><span class="totalreward-cm-ml">` + T(`cm_m_retention`) + `</span></div>`
                + `<div class="totalreward-cm-metric"><span class="totalreward-cm-mv">` + Math.round(s.motivation || 0) + `</span><span class="totalreward-cm-ml">` + T(`cm_m_motivation`) + `</span></div>`
                + `<div class="totalreward-cm-metric"><span class="totalreward-cm-mv">` + Math.round(s.fairness || 0) + `</span><span class="totalreward-cm-ml">` + T(`cm_m_fairness`) + `</span></div>`;
            return ``
                + `<div class="totalreward-completion">`
                +   `<div class="totalreward-cm-head">`
                +     `<div class="totalreward-cm-score">` + score + `<span class="totalreward-cm-score-max">/100</span></div>`
                +     `<div class="totalreward-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="totalreward-cm-metrics">` + metrics + `</div>`
                +   `<div class="totalreward-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="totalreward-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overspent) return window.mySimulation.t(`hint_overspend`);
            if (state.currentPeriod >= 2 && ds.retention < 35) return window.mySimulation.t(`hint_retention`);
            if (state.currentPeriod >= 3 && ds.fairness < 40) return window.mySimulation.t(`hint_council`);
            if (state.currentPeriod >= 3 && ds.motivation < 40) return window.mySimulation.t(`hint_motivation`);
            if (ds.equity >= 70 && ds.retention >= 65 && ds.motivation >= 65 && ds.fairness >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

